Content.Interface:
FUNCTION_BLOCK START_PROC
VAR_INPUT
	CONTROLLER_STATUS:BOOL;
END_VAR
VAR_OUTPUT
	ENABLE_SYSTEM: BOOL;
END_VAR
VAR
	STARTUPTIMER: TON;
END_VAR

Content.Implementation:
	

	IF CONTROLLER_STATUS = TRUE THEN 
		FEP_BootUpComplete := TRUE;
	ELSE 
		FEP_BootUpComplete := FALSE;
	END_IF
		
	StartUpTimer(IN:=FEP_BootUpComplete,PT:=StartUpDelayTime);
		
	IF StartUpTimer.Q  THEN
		ENABLE_SYSTEM := TRUE;
	ELSE 
		ENABLE_SYSTEM := FALSE;
	END_IF
